// MIBTECH building geometry from the architect's plans (mibtechPlanData.ts, generated by docs/research/mibtech-plan-extract.py).
// Pure geometry, no React: merged BufferGeometries per material, in the BUILDING frame of the plans (metres; x along the
// street façade towards the north-east, z towards the street, origin = middle of the façade glass; y up from the pavement).
//
// Heights are NOT in the plans (« plan cotation » only): every one below is a documented provisional value.
//   · ground floor 4.6 m (street photos), floor to floor 3.8 m (chosen by the project owner, provisional; the stair drawn on
//     the plans — 18 treads of 28.2 cm — would rather suggest ≈ 3.5 m by Blondel's rule), slab 0.30 m, suspended ceiling
//     at 2.80 m, window sill 0.90 m / head 2.60 m, WC cubicles 2.10 m, doors 2.10 m.
import * as THREE from "three";
import { MIBTECH_PLANS, type FloorPlan, type PlanPoly } from "./mibtechPlanData";

export const MB_H = {
  ground: 4.6, floor: 3.8, slab: 0.3, ceiling: 2.8, sill: 0.9, head: 2.6, cubicle: 2.1, door: 2.1,
} as const;
export const MB_FLOORS = [1, 2, 3] as const;
export type MbFloor = (typeof MB_FLOORS)[number];
/** level of the finished floor of each office floor (y) */
export const floorY = (f: MbFloor) => MB_H.ground + (f - 1) * MB_H.floor;
/** top of the roof slab */
export const MB_TOP = floorY(3) + MB_H.floor;

export type MbMat = "wall" | "column" | "partition" | "glass" | "frame" | "door" | "cubicle" | "floor" | "ceiling" | "slabEdge" | "lift" | "roof" | "groundWall";
type Acc = { pos: number[]; nor: number[]; uv: number[]; idx: number[] };
const TILE: Record<MbMat, number> = { wall: 2, column: 1, partition: 2, glass: 2, frame: 1, door: 1, cubicle: 1, floor: 1.2, ceiling: 0.6, slabEdge: 1, lift: 1, roof: 4, groundWall: 2.4 };

class Bag {
  m = new Map<MbMat, Acc>();
  get(k: MbMat) { let a = this.m.get(k); if (!a) this.m.set(k, (a = { pos: [], nor: [], uv: [], idx: [] })); return a; }
  build() {
    const out: { key: MbMat; geo: THREE.BufferGeometry }[] = [];
    for (const [key, a] of this.m) {
      if (!a.idx.length) continue;
      const g = new THREE.BufferGeometry();
      g.setAttribute("position", new THREE.Float32BufferAttribute(a.pos, 3));
      g.setAttribute("normal", new THREE.Float32BufferAttribute(a.nor, 3));
      g.setAttribute("uv", new THREE.Float32BufferAttribute(a.uv, 2));
      g.setIndex(a.idx); g.computeBoundingSphere();
      out.push({ key, geo: g });
    }
    return out;
  }
}

const area = (P: PlanPoly) => { let s = 0; for (let i = 0; i < P.length; i++) { const a = P[i], b = P[(i + 1) % P.length]; s += a[0] * b[1] - b[0] * a[1]; } return s / 2; };
/** drop repeated and collinear points (the drawing's polygons carry many) */
function clean(P: PlanPoly): PlanPoly {
  const out: PlanPoly = [];
  for (const q of P) if (!out.length || Math.hypot(q[0] - out[out.length - 1][0], q[1] - out[out.length - 1][1]) > 0.004) out.push(q);
  if (out.length > 2 && Math.hypot(out[0][0] - out[out.length - 1][0], out[0][1] - out[out.length - 1][1]) < 0.004) out.pop();
  for (let i = 0; i < out.length && out.length > 3; ) {
    const a = out[(i + out.length - 1) % out.length], b = out[i], c = out[(i + 1) % out.length];
    const cr = (b[0] - a[0]) * (c[1] - b[1]) - (b[1] - a[1]) * (c[0] - b[0]);
    if (Math.abs(cr) < 1e-5) out.splice(i, 1); else i++;
  }
  return out;
}

/** vertical walls of a polygon prism y0 → y1, normals outward (x/z plan frame: x right, z down) */
function sides(b: Bag, k: MbMat, P: PlanPoly, y0: number, y1: number) {
  const a = b.get(k), t = TILE[k], ccw = area(P) > 0; // area > 0: clockwise on screen (z down) → outward = left of a→b
  let u = 0;
  for (let i = 0; i < P.length; i++) {
    const p = P[i], q = P[(i + 1) % P.length], L = Math.hypot(q[0] - p[0], q[1] - p[1]);
    if (L < 1e-4) continue;
    let nx = (q[1] - p[1]) / L, nz = -(q[0] - p[0]) / L;
    if (!ccw) { nx = -nx; nz = -nz; }
    const o = a.pos.length / 3;
    a.pos.push(p[0], y0, p[1], q[0], y0, q[1], q[0], y1, q[1], p[0], y1, p[1]);
    for (let j = 0; j < 4; j++) a.nor.push(nx, 0, nz);
    a.uv.push(u / t, y0 / t, (u + L) / t, y0 / t, (u + L) / t, y1 / t, u / t, y1 / t);
    u += L;
    // front face where the normal points: (q − p) × up gives (dz, −dx)… pick the winding that faces (nx, nz)
    const fx = (q[1] - p[1]), fz = -(q[0] - p[0]);
    if (fx * nx + fz * nz > 0) a.idx.push(o, o + 2, o + 1, o, o + 3, o + 2); else a.idx.push(o, o + 1, o + 2, o, o + 2, o + 3);
  }
}
/** horizontal cap of a polygon at y, facing up or down */
function cap(b: Bag, k: MbMat, P: PlanPoly, y: number, up: boolean) {
  const a = b.get(k), t = TILE[k];
  const tris = THREE.ShapeUtils.triangulateShape(P.map((q) => new THREE.Vector2(q[0], q[1])), []);
  const o = a.pos.length / 3;
  for (const q of P) { a.pos.push(q[0], y, q[1]); a.nor.push(0, up ? 1 : -1, 0); a.uv.push(q[0] / t, q[1] / t); }
  for (const [i, j, l] of tris) {
    const A = P[i], B = P[j], C = P[l];
    // y-up normal of (A, B, C) in x/z: (B − A) × (C − A) · ŷ = (Bz − Az)(Cx − Ax) − (Bx − Ax)(Cz − Az)
    const ny = (B[1] - A[1]) * (C[0] - A[0]) - (B[0] - A[0]) * (C[1] - A[1]);
    if ((ny > 0) === up) a.idx.push(o + i, o + j, o + l); else a.idx.push(o + i, o + l, o + j);
  }
}
function prism(b: Bag, k: MbMat, P0: PlanPoly, y0: number, y1: number, top = true, bottom = false) {
  const P = clean(P0);
  if (P.length < 3 || Math.abs(area(P)) < 1e-4) return;
  sides(b, k, P, y0, y1);
  if (top) cap(b, k, P, y1, true);
  if (bottom) cap(b, k, P, y0, false);
}

/** One office floor: structure, envelope, partitions, joinery, slab and ceiling (stair flights: see the stair builder). */
function floorParts(f: MbFloor, plan: FloorPlan) {
  const b = new Bag(), y = floorY(f), top = y + MB_H.floor - MB_H.slab;
  for (const P of plan.masonry) prism(b, "wall", P, y, top);
  for (const P of plan.concrete) prism(b, "column", P, y, top);
  for (const P of plan.window) {        // sill, glass, lintel
    prism(b, "wall", P, y, y + MB_H.sill);
    prism(b, "glass", pane(P, 0.03), y + MB_H.sill, y + MB_H.head, false);
    prism(b, "frame", P, y + MB_H.head, y + MB_H.head + 0.06);
    prism(b, "wall", P, y + MB_H.head + 0.06, top);
  }
  for (const P of plan.curtain) {       // glazed walls (the street front is dressed by the façade from the photos)
    prism(b, "glass", P, y + 0.05, y + MB_H.ceiling - 0.05, false);
    prism(b, "frame", P, y, y + 0.05);
    prism(b, "frame", P, y + MB_H.ceiling - 0.05, y + MB_H.ceiling);
  }
  for (const P of plan.glass) prism(b, "glass", P, y, y + MB_H.ceiling, false);
  for (const P of plan.partition) prism(b, "partition", P, y, y + MB_H.ceiling);
  for (const P of plan.cubicle) prism(b, "cubicle", P, y + 0.15, y + MB_H.cubicle);
  for (const P of plan.door) prism(b, "door", P, y, y + MB_H.door);
  for (const P of plan.lift) prism(b, "lift", P, y, top);
  const S = clean(plan.slab[0]);
  cap(b, "floor", S, y + 0.01, true);
  cap(b, "ceiling", S, y + MB_H.ceiling, false);
  sides(b, "slabEdge", S, y - MB_H.slab, y);                  // slab edge, seen between the floors
  cap(b, "ceiling", S, y - MB_H.slab, false);                  // soffit of this floor's slab
  return b.build();
}
/** the glass of a window: a thin pane (thickness t) along the window's long axis, through its middle */
function pane(P: PlanPoly, t: number): PlanPoly {
  let best = 0, ux = 1, uz = 0;
  for (let i = 0; i < P.length; i++) {
    const a = P[i], c = P[(i + 1) % P.length], L = Math.hypot(c[0] - a[0], c[1] - a[1]);
    if (L > best) { best = L; ux = (c[0] - a[0]) / L; uz = (c[1] - a[1]) / L; }
  }
  const cx = P.reduce((s, q) => s + q[0], 0) / P.length, cz = P.reduce((s, q) => s + q[1], 0) / P.length;
  const us = P.map((q) => (q[0] - cx) * ux + (q[1] - cz) * uz), u0 = Math.min(...us), u1 = Math.max(...us);
  const vx = -uz * t / 2, vz = ux * t / 2;
  return [[cx + ux * u0 - vx, cz + uz * u0 - vz], [cx + ux * u1 - vx, cz + uz * u1 - vz], [cx + ux * u1 + vx, cz + uz * u1 + vz], [cx + ux * u0 + vx, cz + uz * u0 + vz]];
}

/** Roofs: the top of floor 3, and the part of floor 1 that floors 2–3 do not cover (just below their floor, never seen through). */
function roofParts() {
  const b = new Bag();
  const S3 = clean(MIBTECH_PLANS[3].slab[0]), S1 = clean(MIBTECH_PLANS[1].slab[0]);
  cap(b, "roof", S3, MB_TOP, true);
  sides(b, "slabEdge", S3, MB_TOP - MB_H.slab, MB_TOP + 0.6);    // roof slab and parapet
  cap(b, "roof", S1, floorY(2) - 0.02, true);
  sides(b, "slabEdge", S1, floorY(2) - MB_H.slab, floorY(2) + 0.5);
  return b.build();
}
/** Ground floor (no plan): the floor-1 footprint as a closed plinth up to the first floor (the street front is dressed
 *  separately from the photos: shops, office entrance). */
function groundParts() {
  const b = new Bag(), S1 = clean(MIBTECH_PLANS[1].slab[0]);
  // every edge but the street front (z ≈ 0): there the ground floor is set back under the floors (MibtechBuilding front())
  for (let i = 0; i < S1.length; i++) {
    const p = S1[i], q = S1[(i + 1) % S1.length];
    if (p[1] > -1.5 && q[1] > -1.5) continue;
    sides(b, "groundWall", [p, q, q], 0, MB_H.ground - MB_H.slab); // degenerate [p, q, q]: the wall p → q, both faces
  }
  return b.build();
}

export type MbParts = { key: MbMat; geo: THREE.BufferGeometry }[];
/** every part of the building, keyed by group: "f1" … "f3" (each floor), "roof", "ground" */
export function buildMibtech(): Record<string, MbParts> {
  const out: Record<string, MbParts> = { roof: roofParts(), ground: groundParts() };
  for (const f of MB_FLOORS) out[`f${f}`] = floorParts(f, MIBTECH_PLANS[f]);
  return out;
}
/** the floor-1 outline (largest), building frame — for the city layer's skip test and the walk solids */
export const MB_OUTLINE: PlanPoly = clean(MIBTECH_PLANS[1].slab[0]);
export function inOutline(P: PlanPoly, x: number, z: number) {
  let c = false;
  for (let i = 0, j = P.length - 1; i < P.length; j = i++) {
    if ((P[i][1] > z) !== (P[j][1] > z) && x < ((P[j][0] - P[i][0]) * (z - P[i][1])) / (P[j][1] - P[i][1]) + P[i][0]) c = !c;
  }
  return c;
}
